const log = [];
async function killOne(pattern, huntMs = 60000) {
  const t0 = Date.now();
  while (Date.now() - t0 < huntMs) {
    const s = sdk.getState();
    if (s.player.hp <= 6) { try { await bot.eatFood(); } catch(e) {} }
    const npc = sdk.findNearbyNpc(pattern, {reachable: true});
    if (!npc) { await sdk.waitForTicks(4); continue; }
    try {
      const r = await bot.attack(npc);
      if (!r.success) { await sdk.waitForTicks(3); continue; }
    } catch(e) { await sdk.waitForTicks(3); continue; }
    const t1 = Date.now();
    while (Date.now() - t1 < 25000) {
      await sdk.waitForTicks(3);
      const st = sdk.getState();
      if (st.player.hp <= 5) { try { await bot.eatFood(); } catch(e) {} }
      if (!st.player.combat.inCombat) break;
    }
    // grab any coin drop nearby
    try {
      const c = await sdk.scanFindGroundItem(/coins/i, 10);
      if (c) { const pr = await bot.pickupItem(c); log.push('picked coins: ' + pr.success); }
    } catch(e) {}
    return true;
  }
  return false;
}
